        vm.assume(_number < 2 ** 63);
        bytes32 hashBefore;
        try c.hash() returns (bytes32 __r) { hashBefore = __r; } catch { return; }
        bytes32 batcherBefore;
        try c.batcherHash() returns (bytes32 __r) { batcherBefore = __r; } catch { return; }
